// Platform IDs: 8 characters from a 30-letter alphabet with no look-alikes
// (no 0/O, 1/I/L, U), shown as two groups: K7QM-4XHT. Generated by Postgres
// (gen_person_ref) so they're unique across every organization.

const REF = /^[2-9A-HJKMNP-TV-Z]{8}$/;

/** "k7qm 4xht", "K7QM4XHT", "k7qm-4xht" → "K7QM-4XHT"; anything else → null. */
export function normalizeRef(input: string): string | null {
  const s = input.toUpperCase().replace(/[\s-]/g, "");
  return REF.test(s) ? `${s.slice(0, 4)}-${s.slice(4)}` : null;
}

/** What to show for a person: their organization's own code if they have one, else the platform ID. */
export function displayId(p: { code?: string | null; ref: string }) {
  return p.code || p.ref;
}
